public class StringMethodsDemo {
    public static void main(String[] args) {
        String log = "2024-10-15 [ERROR] DatabaseConnectionTimeout in pool-1";

        // 1. Length inspection
        System.out.println("Total Length: " + log.length());

        // 2. Character at index
        System.out.println("First Char: " + log.charAt(0));

        // 3. Finding positions
        int bracketOpen = log.indexOf('[');
        int bracketClose = log.indexOf(']');
        System.out.println("Bracket indices: " + bracketOpen + " to " + bracketClose);

        // 4. Extracting slice (exclusive end index)
        String level = log.substring(bracketOpen + 1, bracketClose);
        System.out.println("Log Level: " + level); // "ERROR"

        // 5. Prefix, Suffix, and Contains checks
        System.out.println("Starts with timestamp: " + log.startsWith("2024"));
        System.out.println("Ends with pool-1: " + log.endsWith("pool-1"));
        System.out.println("Contains Timeout: " + log.contains("Timeout"));

        // 6. Non-existent substring returns -1
        int missingIndex = log.indexOf("WARNING");
        System.out.println("Missing Index: " + missingIndex); // -1
    }
}

