public class ParenthesesExtractor {
    public static void main(String[] args) {
        String record = "Order placed (ID: 98412) successfully";
        int open = record.indexOf('(');
        int close = record.indexOf(')');
        String content = record.substring(open + 1, close);
        System.out.println("Content: " + content);
    }
}

